import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Entitlements model","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Entitlements model | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/entitlements"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Entitlements model | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/entitlements"}]]},"headers":[],"relativePath":"developer-guide/entitlements.md","filePath":"developer-guide/entitlements.md","lastUpdated":1788122084000}'),n={name:"developer-guide/entitlements.md"};function s(r,e,c,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="entitlements-model" tabindex="-1">Entitlements model <a class="header-anchor" href="#entitlements-model" aria-label="Permalink to &quot;Entitlements model&quot;">​</a></h1><p>How to <strong>build</strong> a licensed module end-to-end: <a href="/developer-guide/module-development">Module Development Standard</a>. Platform freeze: <a href="/getting-started/platform-freeze">platform-freeze.md</a>. Long-term licensing convention: <a href="/architecture/module-licensing">Module Licensing</a>.</p><h2 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h2><p>The platform does <strong>not</strong> sell plans or features. Licensing is based entirely on <strong>workspace module subscriptions</strong>.</p><p><strong>Licensing and authorization are separate concerns.</strong></p><table tabindex="0"><thead><tr><th>Layer</th><th>Concern</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td>Core Platform</td><td>Always-on</td><td>Platform capabilities (not modules, not billed)</td><td>Auth, users, roles, dashboard, billing, marketplace shell</td></tr><tr><td>Module</td><td>Licensing</td><td>Independently installable business domain</td><td>Leads, Tasks, Communication Templates</td></tr><tr><td>Spatie Permission</td><td>Authorization</td><td>User access within an installed module</td><td><code>leads.view</code>, <code>tasks.create</code></td></tr><tr><td>Workspace module subscription</td><td>License row</td><td>Links a workspace to a module</td><td>Acme → Leads (<code>source=included</code>)</td></tr></tbody></table><p>There are <strong>no</strong> plan tiers, plan modules, plan features, feature catalogs, or module usage limits (e.g. “100 leads”).</p><p>A purchased or included module makes a business domain <strong>available</strong> to the workspace. It does <strong>not</strong> grant every user access. Admins assign Spatie roles and permissions to control who can use that domain. Tenant role edit and the permissions matrix only list core permission groups plus groups for <strong>installed</strong> modules (see <a href="/developer-guide/tenant-rbac#role-assignment-ui-filter-entitlement">Tenant RBAC</a>).</p><h2 id="core-platform-vs-modules" tabindex="-1">Core Platform vs modules <a class="header-anchor" href="#core-platform-vs-modules" aria-label="Permalink to &quot;Core Platform vs modules&quot;">​</a></h2><p>Core Platform capabilities live in <code>config/core-platform.php</code> and are always available.</p><p>Business modules live in the <code>modules</code> catalog. <strong>Commercial flags</strong> (<code>is_default_included</code>, <code>is_billable</code>, <code>monthly_price</code>, <code>yearly_price</code>) are the source of truth for Marketplace pricing — keep marketing/docs in sync with <code>CatalogSeeder</code> and register_* migrations.</p><p><strong>Marketing availability</strong> (<code>availability</code>: <code>available</code> | <code>in_progress</code> | <code>planned</code>) is separate from commercial <code>status</code> (<code>draft</code> | <code>published</code> | <code>deprecated</code>). The EloSync website reads both via unauthenticated <code>GET /api/central/v1/public/modules</code> (paid tags use each module’s catalog <code>currency</code>, e.g. USD — not the workspace default in system settings).</p><h3 id="published-catalog-current" tabindex="-1">Published catalog (current) <a class="header-anchor" href="#published-catalog-current" aria-label="Permalink to &quot;Published catalog (current)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Slug</th><th>Name</th><th>Default included</th><th>Billable</th><th>Monthly</th><th>Yearly</th></tr></thead><tbody><tr><td><code>leads</code></td><td>Leads</td><td>Yes</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>tasks</code></td><td>Tasks</td><td>Yes</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>contacts</code></td><td>Contacts</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>companies</code></td><td>Companies</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>calendar</code></td><td>Calendar</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>meetings</code></td><td>Meetings</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>activities</code></td><td>Activities</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>opportunities</code></td><td>Opportunities</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>quotations</code></td><td>Quotations</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>contracts</code></td><td>Contracts</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>communication-templates</code></td><td>Communication Templates</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>email</code></td><td>Email</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>team-chat</code></td><td>Team Chat</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>help-desk</code></td><td>Help Desk</td><td>No (free opt-in)</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>branded</code></td><td>Branded</td><td>No</td><td><strong>Yes</strong></td><td><strong>$29</strong></td><td><strong>$290</strong></td></tr><tr><td><code>storage</code></td><td>Storage</td><td>No</td><td>No</td><td>$0</td><td>$0</td></tr><tr><td><code>storage-10</code></td><td>Storage 10 GB</td><td>No</td><td><strong>Yes</strong></td><td><strong>$4</strong></td><td><strong>$40</strong></td></tr><tr><td><code>storage-50</code></td><td>Storage 50 GB</td><td>No</td><td><strong>Yes</strong></td><td><strong>$12</strong></td><td><strong>$120</strong></td></tr><tr><td><code>storage-100</code></td><td>Storage 100 GB</td><td>No</td><td><strong>Yes</strong></td><td><strong>$20</strong></td><td><strong>$200</strong></td></tr><tr><td><code>storage-500</code></td><td>Storage 500 GB</td><td>No</td><td><strong>Yes</strong></td><td><strong>$75</strong></td><td><strong>$750</strong></td></tr><tr><td><code>storage-1000</code></td><td>Storage 1000 GB</td><td>No</td><td><strong>Yes</strong></td><td><strong>$120</strong></td><td><strong>$1200</strong></td></tr></tbody></table><p><strong>Default-included</strong> modules (<code>is_default_included = true</code>, <code>is_billable = false</code>):</p><table tabindex="0"><thead><tr><th>Slug</th><th>Notes</th></tr></thead><tbody><tr><td><code>leads</code></td><td>CRM pipeline — auto-installed (<code>source=included</code>)</td></tr><tr><td><code>tasks</code></td><td>Work items — auto-installed (<code>source=included</code>)</td></tr><tr><td><code>todos</code></td><td>Personal checklists — auto-installed (<code>source=included</code>)</td></tr></tbody></table><p>They are not cancellable by workspace owners (platform admin may <strong>deactivate</strong>).</p><p><strong>Free Marketplace opt-in</strong> (<code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>$0</code>): Contacts, Companies, Calendar, Meetings, Activities, Opportunities, Quotations, Contracts (Sales category), Communication Templates, Email (Communication category), Team Chat (Collaboration category), Help Desk (Operations category). Tenants install from Marketplace; owners can remove them. Quotations and Contracts require Opportunities first (hard <code>module_dependencies</code>).</p><p><strong>Paid Marketplace</strong> (<code>is_billable = true</code>): Branded at USD <strong>$29/month</strong> or <strong>$290/year</strong> (custom domain + white-label notifications); Automation at <strong>$29/$290</strong>; Storage capacity packs (<code>storage-10</code> … <code>storage-1000</code>) as listed above (require free <code>storage</code>).</p><p>New default-included modules for <strong>existing</strong> production workspaces are registered via idempotent <strong>data migrations</strong> (<code>DefaultModuleRegistrar</code>), not <code>db:seed</code>. See <a href="/deployment/module-development">module-development production</a>.</p><p>Schema remains flexible so free modules can become paid for <em>new</em> customers later without redesign (<code>is_billable</code>, pricing columns, <code>source</code>).</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>active_modules(workspace) =</span></span>
<span class="line"><span>  workspace_module_subscriptions</span></span>
<span class="line"><span>    WHERE status IN (trial, active)</span></span>
<span class="line"><span>    AND (ends_at IS NULL OR ends_at &gt; now)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>has_module(workspace, slug) =</span></span>
<span class="line"><span>  module with that slug is in active_modules AND module.is_active</span></span>
<span class="line"><span></span></span>
<span class="line"><span>core = config(&#39;core-platform.capabilities&#39;)</span></span></code></pre></div><p>Cached as <code>workspace:{id}:entitlements</code> (1 hour). Invalidated on install/cancel/deactivate/status change.</p><p>API: <code>GET /api/central/v1/tenants/{tenant}/entitlements</code></p><p>Returns <code>{ core, modules }</code> for the tenant application to register licensed domains. User permissions come from Spatie Roles &amp; Permissions, not from this payload.</p><h2 id="routing-licensing-authorization" tabindex="-1">Routing (licensing + authorization) <a class="header-anchor" href="#routing-licensing-authorization" aria-label="Permalink to &quot;Routing (licensing + authorization)&quot;">​</a></h2><p>Tenant routes should pair middleware:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Route::middleware([&#39;auth:tenant-api&#39;, &#39;module:leads&#39;, &#39;can:leads.view&#39;])-&gt;group(...)</span></span></code></pre></div><ol><li><code>module:{slug}</code> — workspace owns/has the licensed module (<code>EnsureModule</code>)</li><li><code>can:{permission}</code> — authenticated user has the Spatie permission</li></ol><p>Only then allow access.</p><h2 id="marketplace-install-rules" tabindex="-1">Marketplace install rules <a class="header-anchor" href="#marketplace-install-rules" aria-label="Permalink to &quot;Marketplace install rules&quot;">​</a></h2><p>Published catalog: tenant <code>GET /marketplace/modules</code> / <code>POST …/purchase</code>, or central install via <code>POST /tenants/{tenant}/modules</code>.</p><p>Tenant Marketplace responses convert catalog amounts into the workspace currency for <strong>display only</strong> (<code>base_*</code> / <code>billed_currency</code> preserve the catalog/Stripe charge currency). See <a href="/api/tenant-v1-marketplace#display-currency-conversion">Tenant Marketplace API</a>.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Behavior</th></tr></thead><tbody><tr><td>Module must be <code>published</code> and <code>is_active</code></td><td>Validation error otherwise</td></tr><tr><td>Duplicate active/pending/trial install</td><td>Rejected</td></tr><tr><td>Reinstall after cancel/suspend</td><td>Same <code>tenant_id</code>+<code>module_id</code> row is reactivated (<code>updateOrCreate</code>)</td></tr><tr><td>Required dependencies (<code>module_dependencies</code>, <code>is_optional=false</code>)</td><td>Must already be installed; marketplace detail returns <code>missing_required_modules</code></td></tr><tr><td>Non-billable module</td><td><code>status=active</code> immediately, <code>source=included</code> if <code>is_default_included</code> else <code>purchased</code></td></tr><tr><td>Billable module (<code>is_billable</code> + price &gt; 0)</td><td><code>status=pending</code> until Billing Engine settles payment</td></tr></tbody></table><p>Install body: <code>{ &quot;module_id&quot;: int, &quot;billing_cycle?&quot;: &quot;monthly&quot; | &quot;yearly&quot; }</code> (central) or <code>POST /marketplace/modules/{module}/purchase</code> with optional <code>billing_cycle</code> (tenant).</p><h2 id="cancel-deactivate-rules" tabindex="-1">Cancel / deactivate rules <a class="header-anchor" href="#cancel-deactivate-rules" aria-label="Permalink to &quot;Cancel / deactivate rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Who</th><th>Included modules</th><th>Purchased / opt-in modules</th></tr></thead><tbody><tr><td><strong>Cancel</strong> (<code>POST /module-subscriptions/{id}/cancel</code>)</td><td>Central <code>module-subscriptions.update</code></td><td><strong>Blocked</strong> — use deactivate</td><td>Sets <code>cancelled</code>, <code>ends_at=now</code></td></tr><tr><td><strong>Cancel</strong> (<code>POST /marketplace/modules/{module}/cancel</code>)</td><td>Tenant <code>marketplace.purchase</code></td><td><strong>Blocked</strong></td><td>Same cancel semantics for the current workspace</td></tr><tr><td><strong>Deactivate</strong> (<code>POST /module-subscriptions/{id}/deactivate</code>)</td><td>Central <code>module-subscriptions.deactivate</code></td><td>Allowed (platform admin)</td><td>Sets <code>suspended</code></td></tr></tbody></table><p>Cancel eligibility is based on catalog <code>is_default_included</code> (not subscription <code>source</code>). Cancel removes entitlements immediately. Hard dependents must be removed first (<code>blocking_dependents</code> on marketplace detail). Deactivate is the platform-admin override for included core modules.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><p><code>module_dependencies</code> supports hard/optional deps for marketplace modules. Leads and Tasks have none today. <code>MarketplaceService::detailForTenant</code> exposes <code>required_modules</code>, <code>optional_modules</code>, <code>missing_required_modules</code>, <code>already_installed</code>, <code>can_cancel</code>, and <code>blocking_dependents</code>. Dependency summaries are enriched via <code>summarizeModulesForTenant</code> with pricing and install flags so the tenant SPA can enable a missing required module (and show its subscription fee) from the detail drawer.</p><h2 id="billing" tabindex="-1">Billing <a class="header-anchor" href="#billing" aria-label="Permalink to &quot;Billing&quot;">​</a></h2><p>Each workspace has a consolidated billing profile (<code>billing_anchor_day</code>, <code>billing_cycle</code>, <code>proration_mode</code>, <code>next_billing_at</code>). One invoice per cycle for all <strong>billable active</strong> modules via <code>billing:run-consolidated</code>. Mid-cycle installs use proration modes: <code>prorated</code> | <code>free_until_next</code> | <code>none</code>. See <a href="/developer-guide/billing-engine">billing/billing-engine.md</a>.</p>`,43)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
